static bool CheckCounts(List<string> shops, List<int> expected)
{
    List<string> requested = new List<string>(shops);
    Source.Calls.Clear();
    List<int> actual = Practice.CountsAsync(shops).GetAwaiter().GetResult();
    return actual.SequenceEqual(expected) && Source.Calls.SequenceEqual(requested);
}
